using namespace std;
using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int64> A(N + 1);
    for (int i = 0; i <= N; i++) {
        cin >> A[i];
    }

    // If root is not leaf, but depth 0 must have A[0] leaves
    if (N == 0) {
        if (A[0] == 1) cout << 1 << "\n";
        else cout << -1 << "\n";
        return 0;
    }

    if (A[0] != 1) {
        cout << -1 << "\n";
        return 0;
    }

    vector<int64> max_nodes_at(N + 2, 0);
    max_nodes_at[N] = A[N];

    // Propagate upwards to see max possible nodes at each depth
    for (int d = N - 1; d >= 0; d--) {
        // Each node at depth d+1 has a parent at depth d
        // So max nodes at depth d is at most the number of nodes at depth d+1
        // But also we must have at least A[d] leaves at this depth
        int64 possible = max_nodes_at[d + 1] + A[d]; // This formula: each node at d+1 can be from a node at d, plus we need A[d] leaves
        // Actually, each node at depth d can have at most 2 children.
        // So number of nodes at depth d = ceil(nodes_at_d+1 / 2) ??? Not exactly. 
        // Let's think: total nodes at depth d = leaves_at_d + internal_nodes_at_d
        // Leaves at d = A[d]. Internal nodes at d = number of nodes at d+1 (since each node at d+1 has a parent at d)
        // So total nodes at d = A[d] + nodes_at_d+1
        // But wait, internal nodes at d can be less than nodes_at_d+1 if some nodes at d+1 share a parent? No, each node at depth d+1 has exactly one parent at depth d.
        // So number of parents = nodes_at_d+1.
        // Therefore total nodes at depth d = A[d] + nodes_at_d+1.
        max_nodes_at[d] = A[d] + max_nodes_at[d + 1];
    }

    int64 total_nodes = 0;
    int64 nodes_at_current = 1; // root

    for (int d = 0; d <= N; d++) {
        // At depth d, we have nodes_at_current nodes available
        if (A[d] > nodes_at_current) {
            cout << -1 << "\n";
            return 0;
        }
        total_nodes += nodes_at_current;
        // Next depth: each node can have at most 2 children, but at least enough to cover A[d+1] leaves
        // Also we cannot exceed max_nodes_at[d+1] which we computed
        if (d < N) {
            int64 next_possible = min(2 * nodes_at_current, max_nodes_at[d + 1]);
            if (next_possible < A[d + 1]) {
                cout << -1 << "\n";
                return 0;
            }
            nodes_at_current = next_possible;
        }
    }

    cout << total_nodes << "\n";
    return 0;
}

