int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> A(N + 1);
    for (int i = 0; i <= N; ++i) cin >> A[i];

    // Special case: depth 0 tree
    if (N == 0) {
        cout << (A[0] == 1 ? 1 : -1) << '\n';
        return 0;
    }

    // maxNodes[d] = maximum possible number of nodes at depth d
    // considering only constraints from root down to depth d.
    vector<long long> maxNodes(N + 1);
    maxNodes[0] = 1;
    for (int d = 0; d < N; ++d) {
        if (maxNodes[d] < A[d]) {
            cout << -1 << '\n';
            return 0;
        }
        long long internal = maxNodes[d] - A[d];
        if (internal > (long long)4e18 / 2) internal = (long long)4e18 / 2;
        maxNodes[d + 1] = internal * 2;
    }

    if (maxNodes[N] < A[N]) {
        cout << -1 << '\n';
        return 0;
    }

    // need[d] = maximum allowed nodes at depth d so that
    // lower levels can satisfy leaf counts.
    vector<long long> need(N + 1);
    need[N] = A[N];
    for (int d = N - 1; d >= 0; --d) {
        // To support need[d+1] nodes at next level, we need at least
        // ceil(need[d+1] / 2) internal/total parent nodes before adding leaves A[d].
        need[d] = A[d] + (need[d + 1] + 1) / 2;
    }

    if (need[0] > 1 || A[0] > 1) {
        cout << -1 << '\n';
        return 0;
    }

    long long ans = 0;
    long long cur = 1; // actual number of nodes at current depth, maximized
    for (int d = 0; d <= N; ++d) {
        cur = min(cur, need[d] > (long long)4e18 ? (long long)4e18 : maxNodes[d]);
        if (cur < A[d]) {
            cout << -1 << '\n';
            return 0;
        }
        ans += cur;
        if (d == N) break;
        long long internal = cur - A[d];
        if (internal > (long long)4e18 / 2) internal = (long long)4e18 / 2;
        cur = internal * 2;
        cur = min(cur, maxNodes[d + 1]);
    }

    cout << ans << '\n';
    return 0;
}

