import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long[] A = new long[N + 1];
        for (int i = 0; i <= N; i++) A[i] = fs.nextLong();

        // Special case: only root exists
        if (N == 0) {
            System.out.println(A[0] == 1 ? 1 : -1);
            return;
        }

        // maxPossible[d] = maximum number of nodes that can exist at depth d
        // while still being able to realize leaves in deeper levels.
        long[] maxPossible = new long[N + 1];
        maxPossible[N] = A[N];

        for (int d = N - 1; d >= 0; d--) {
            // To support maxPossible[d+1] nodes at next depth,
            // we need at least ceil(maxPossible[d+1] / 2) internal nodes here,
            // plus leaves A[d].
            long needParents = (maxPossible[d + 1] + 1) / 2;
            maxPossible[d] = A[d] + needParents;

            // Overflow guard is not really necessary under typical constraints,
            // but keep values bounded.
            if (maxPossible[d] < 0) {
                System.out.println(-1);
                return;
            }
        }

        // Root must be exactly one node.
        if (maxPossible[0] != 1) {
            System.out.println(-1);
            return;
        }

        long ans = 0;
        long current = 1; // actual number of nodes at current depth, maximized greedily

        for (int d = 0; d <= N; d++) {
            if (current < A[d]) {
                System.out.println(-1);
                return;
            }

            ans += current;

            long internal = current - A[d];
            if (d == N) {
                if (internal != 0) {
                    System.out.println(-1);
                    return;
                }
            } else {
                long next = internal * 2;
                current = Math.min(next, maxPossible[d + 1]);
            }
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

