#include <stdio.h>
#include <stdlib.h>

int main() {
    int N;
    scanf("%d", &N);

    long long *A = (long long*)malloc((N + 1) * sizeof(long long));
    for (int i = 0; i <= N; i++) {
        scanf("%lld", &A[i]);
    }

    // If at depth N we have leaves, but at depth N-1 we have 0 leaves, impossible unless N=0
    if (N > 0 && A[N] > 0 && A[N-1] == 0) {
        printf("-1\n");
        free(A);
        return 0;
    }

    long long total_vertices = 0;
    long long nodes_at_current = 0; // nodes at depth d that are not leaves

    // Start from bottom
    nodes_at_current = A[N];
    total_vertices = A[N];

    for (int d = N - 1; d >= 0; d--) {
        // Each node at depth d can have at most 2 children at depth d+1
        // nodes_at_current is number of nodes at depth d+1 (both leaves and internal)
        // We need at least A[d] leaves at depth d
        // The rest of nodes_at_current must be children of internal nodes at depth d
        // Maximum possible internal nodes at depth d is nodes_at_current / 2 (since each internal node has 2 children)
        // But we also need exactly A[d] leaves at depth d

        long long max_possible_internal = nodes_at_current / 2;
        long long leaves_needed = A[d];

        if (leaves_needed > nodes_at_current) {
            // Not enough nodes at depth d+1 to have that many leaves at depth d
            printf("-1\n");
            free(A);
            return 0;
        }

        long long internal_at_d = nodes_at_current - leaves_needed;
        if (internal_at_d > max_possible_internal) {
            printf("-1\n");
            free(A);
            return 0;
        }

        total_vertices += leaves_needed + internal_at_d;
        nodes_at_current = leaves_needed + internal_at_d;
    }

    // At depth 0 we must have exactly 1 node (root)
    if (nodes_at_current != 1) {
        printf("-1\n");
    } else {
        printf("%lld\n", total_vertices);
    }

    free(A);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *A = (ll *)malloc((N + 1) * sizeof(ll));
    ll *cap = (ll *)malloc((N + 1) * sizeof(ll));
    if (!A || !cap) return 0;

    for (int i = 0; i <= N; i++) scanf("%lld", &A[i]);

    // Root-only special case
    if (N == 0) {
        if (A[0] == 1) printf("1\n");
        else printf("-1\n");
        free(A);
        free(cap);
        return 0;
    }

    // At depth 0, there can be at most 1 node.
    cap[0] = 1;
    if (A[0] > cap[0]) {
        printf("-1\n");
        free(A);
        free(cap);
        return 0;
    }

    // cap[d] = maximum possible number of nodes at depth d
    // considering only constraints from depths 0..d-1.
    for (int d = 0; d < N; d++) {
        ll internal = cap[d] - A[d];
        if (internal < 0) {
            printf("-1\n");
            free(A);
            free(cap);
            return 0;
        }
        // children of internal nodes
        if (internal > (1LL << 60)) cap[d + 1] = (1LL << 60);
        else {
            ll nxt = internal * 2;
            cap[d + 1] = nxt;
        }
    }

    // Now greedily determine the maximum feasible number of nodes per depth
    // from bottom to top.
    ll *nodes = (ll *)malloc((N + 1) * sizeof(ll));
    if (!nodes) return 0;

    nodes[N] = A[N];
    if (nodes[N] > cap[N]) {
        printf("-1\n");
        free(A); free(cap); free(nodes);
        return 0;
    }

    for (int d = N - 1; d >= 0; d--) {
        // Need enough nodes at depth d to support nodes[d+1]:
        // internal nodes at depth d must be at least ceil(nodes[d+1]/2),
        // so total nodes[d] >= A[d] + ceil(nodes[d+1]/2).
        ll need = A[d] + (nodes[d + 1] + 1) / 2;
        if (need > cap[d]) {
            printf("-1\n");
            free(A); free(cap); free(nodes);
            return 0;
        }
        // To maximize total vertices, take as many as possible.
        nodes[d] = cap[d];
    }

    ll ans = 0;
    for (int d = 0; d <= N; d++) ans += nodes[d];

    printf("%lld\n", ans);

    free(A);
    free(cap);
    free(nodes);
    return 0;
}
